
#[cfg(test)]mod freezing80_shock87_request_development_tests {
 use super::*;const OTHER:u32=0x71234567;
 fn world()->World{let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.clear();w.learned_skills.extend([80,87]);w.mp=Some([1,100]);w.hp=Some([1,100]);let id=w.own_actor().unwrap().id;w.actors.get_mut(&id).unwrap().walk_action=50;let mut a=w.own_actor().unwrap().clone();a.id=OTHER;a.incarnation+=10;a.x+=1;w.actors.insert(OTHER,a);w}
 #[test]fn freezing_is_selector_only_and_rejects_any_supplied_actor(){let w=world();let before=serde_json::to_value(&w).unwrap();assert_eq!(request(&w,80,None).unwrap(),vec![20,9,7]);for id in [OTHER,w.own_actor().unwrap().id]{assert!(request(&w,80,Some(id)).is_err());}assert_eq!(reuse_millis(80),3000);assert_eq!(serde_json::to_value(&w).unwrap(),before);}
 #[test]fn shock_encodes_actor_xy_for_both_formal_walk_families_without_local_stun(){let mut w=world();for stance in [50,54]{let own=w.own_actor().unwrap().id;w.actors.get_mut(&own).unwrap().walk_action=stance;let before=serde_json::to_value(&w).unwrap();let a=&w.actors[&OTHER];let mut b=vec![20,10,6];b.extend(OTHER.to_le_bytes());b.extend(a.x.to_le_bytes());b.extend(a.y.to_le_bytes());assert_eq!(request(&w,87,Some(OTHER)).unwrap(),b);assert_eq!(b.len(),11);assert_eq!(serde_json::to_value(&w).unwrap(),before);}assert_eq!(reuse_millis(87),8000);}
 #[test]fn shock_rejects_other_stance_range_and_target_life_without_fallback(){for stance in [0,4,49,51,53,55]{let mut w=world();let own=w.own_actor().unwrap().id;w.actors.get_mut(&own).unwrap().walk_action=stance;assert!(request(&w,87,Some(OTHER)).is_err());}let mut w=world();w.actors.get_mut(&OTHER).unwrap().x+=1;assert!(request(&w,87,Some(OTHER)).is_err());w.actors.get_mut(&OTHER).unwrap().x-=1;w.actors.get_mut(&OTHER).unwrap().dead=true;assert!(request(&w,87,Some(OTHER)).is_err());for id in [None,Some(w.own_actor().unwrap().id),Some(0xf1234567)]{assert!(request(&w,87,id).is_err());}}
 #[test]fn book_MP_and_paralysis_gates_are_independent_of_impact_graphics(){for skill in [80,87]{let mut w=world();let target=if skill==87{Some(OTHER)}else{None};w.learned_skills.remove(&skill);assert!(request(&w,skill,target).is_err());w.learned_skills.insert(skill);w.mp=Some([0,100]);assert!(request(&w,skill,target).is_err());w.mp=Some([1,100]);w.movement_blocks.insert(24);assert!(request(&w,skill,target).is_err());}}
}
